import{c as a,Q as d,j as e,m as i}from"./chunks/framework.CWBTDBPu.js";const k=JSON.parse('{"title":"YuChat 安装部署","description":"","frontmatter":{"title":"YuChat 安装部署"},"headers":[],"relativePath":"plugins/items/yu-chat/install.md","filePath":"plugins/items/yu-chat/install.md"}'),s={name:"plugins/items/yu-chat/install.md"};function l(o,t,r,h,c,n){return d(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="yuchat-安装部署" tabindex="-1">YuChat 安装部署 <a class="header-anchor" href="#yuchat-安装部署" aria-label="Permalink to &quot;YuChat 安装部署&quot;">​</a></h1><h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>Java</td><td>Java 8 及以上。源码以 <code>sourceCompatibility/targetCompatibility = 1.8</code> 构建。</td></tr><tr><td>服务端</td><td>Spigot、Paper、Paper 衍生端，以及 Mohist、Arclight、Youer 等兼容 Bukkit API 的混合端。</td></tr><tr><td>Minecraft</td><td>目标适配 <code>1.8.x-1.26.x</code>。源码使用 Spigot API <code>1.8.8-R0.1-SNAPSHOT</code> 编译，建议在正式服同版本测试后上线。</td></tr><tr><td>数据库</td><td>默认 SQLite；跨服共享或多端同步建议使用 MySQL。</td></tr><tr><td>可选依赖</td><td>PlaceholderAPI、LuckPerms、Vault、PlayerPoints。</td></tr><tr><td>网络访问</td><td>首次启动会从 Maven Central 下载运行时依赖；bStats 统计也会尝试访问统计服务。</td></tr></tbody></table><h2 id="兼容范围" tabindex="-1">兼容范围 <a class="header-anchor" href="#兼容范围" aria-label="Permalink to &quot;兼容范围&quot;">​</a></h2><p>YuChat 的环境适配范围与 YuRandomTeleport 保持一致。</p><table tabindex="0"><thead><tr><th>兼容范围</th><th>说明</th></tr></thead><tbody><tr><td>Minecraft 版本</td><td>目标适配 <code>1.8.x-1.26.x</code>。</td></tr><tr><td>Bukkit 系服务端</td><td>Spigot、Paper、Paper 衍生端。</td></tr><tr><td>混合端</td><td>Mohist、Arclight、Youer 等 Bukkit API 混合端。</td></tr><tr><td>Java 运行时</td><td>Java 8 及以上。Java 9+ 如果遇到类加载器反射限制，可按控制台提示添加 <code>--add-opens java.base/java.net=ALL-UNNAMED</code>。</td></tr><tr><td>存储后端</td><td>SQLite 单服文件库；MySQL 跨服共享。</td></tr></tbody></table><h2 id="版本获取" tabindex="-1">版本获取 <a class="header-anchor" href="#版本获取" aria-label="Permalink to &quot;版本获取&quot;">​</a></h2><p>YuChat 提供免费版和高级版：</p><table tabindex="0"><thead><tr><th>版本</th><th>获取方式</th></tr></thead><tbody><tr><td>免费版 <code>1.0.6</code></td><td>在 <a href="https://qm.qq.com/q/xiwJYBYdh0" target="_blank" rel="noreferrer">Yu 插件交流群</a> 获取。</td></tr><tr><td>高级版</td><td>需要高级功能、持续更新或完整支持时，请在 <a href="https://afdian.com/item/5913558252bc11f1a1e15254001e7c00" target="_blank" rel="noreferrer">爱发电赞助获取</a>。</td></tr></tbody></table><h2 id="部署到服务端" tabindex="-1">部署到服务端 <a class="header-anchor" href="#部署到服务端" aria-label="Permalink to &quot;部署到服务端&quot;">​</a></h2><ol><li>停止服务端。</li><li>将获取到的 YuChat jar 放入服务端 <code>plugins/</code> 目录。</li><li>按需安装 PlaceholderAPI、LuckPerms、Vault、PlayerPoints。</li><li>启动服务端，等待插件生成 <code>plugins/YuChat/</code> 下的配置文件。</li><li>首次启动时确认运行时依赖下载完成，控制台应出现 <code>YuChat 已启用。</code>。</li><li>进入游戏执行 <code>/yc help</code>、<code>/chat help</code> 或 <code>/yuchat help</code> 检查命令是否注册成功。</li></ol><h2 id="运行时依赖" tabindex="-1">运行时依赖 <a class="header-anchor" href="#运行时依赖" aria-label="Permalink to &quot;运行时依赖&quot;">​</a></h2><p>YuChat 在启动阶段会把这些依赖下载到 <code>plugins/YuChat/libs/</code>，发布版还会把隔离 core 解压到 <code>plugins/YuChat/runtime/</code>。</p><table tabindex="0"><thead><tr><th>依赖</th><th>版本</th><th>用途</th></tr></thead><tbody><tr><td>HikariCP</td><td><code>4.0.3</code></td><td>MySQL/SQLite 连接池。</td></tr><tr><td>sqlite-jdbc</td><td><code>3.51.3.0</code></td><td>SQLite 文件数据库驱动。</td></tr><tr><td>mysql-connector-j</td><td><code>9.6.0</code></td><td>MySQL 数据库驱动。</td></tr><tr><td>slf4j-api / slf4j-nop</td><td><code>2.0.17</code></td><td>HikariCP 日志依赖。</td></tr></tbody></table><p>默认会校验远程仓库提供的 SHA-256 或 SHA-1。若服务器无法访问 Maven Central，可手动下载对应 jar 放入 <code>plugins/YuChat/libs/</code> 后重启。</p><h2 id="首次配置检查" tabindex="-1">首次配置检查 <a class="header-anchor" href="#首次配置检查" aria-label="Permalink to &quot;首次配置检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>默认值</th><th>建议</th></tr></thead><tbody><tr><td><code>storage.type</code></td><td><code>sqlite</code></td><td>单服保持默认；多子服共享改为 <code>mysql</code>。</td></tr><tr><td><code>storage.table-prefix</code></td><td><code>yuchat_</code></td><td>多插件共库时保持独立前缀。</td></tr><tr><td><code>chat-format.component-broadcast.enabled</code></td><td><code>false</code></td><td>需要聊天内悬浮时再开启，默认更兼容聊天记录和群组互联。</td></tr><tr><td><code>chat-format.format</code></td><td><code>{prefix} {title} {nickname} &amp;8&gt;&gt;&gt; &amp;f{message} {suffix}</code></td><td>按服务器聊天样式调整。</td></tr><tr><td><code>placeholder.expansion.enabled</code></td><td><code>true</code></td><td>需要 TAB、菜单、计分板读取 <code>%yuchat_*%</code> 时保持开启。</td></tr><tr><td><code>prefix-suffix.enabled</code></td><td><code>true</code></td><td>安装 LuckPerms 后检查 prefix/suffix/meta 组合。</td></tr><tr><td><code>display.tab.enabled</code></td><td>配置文件内控制</td><td>若 TAB 插件接管列表名，建议改在 TAB 插件中使用 YuChat PAPI 变量。</td></tr><tr><td><code>library.verify-checksum</code></td><td><code>true</code></td><td>推荐保持开启，避免损坏或被替换的依赖 jar 被加载。</td></tr></tbody></table><h2 id="mysql-跨服共享" tabindex="-1">MySQL 跨服共享 <a class="header-anchor" href="#mysql-跨服共享" aria-label="Permalink to &quot;MySQL 跨服共享&quot;">​</a></h2><p>将 <code>storage.type</code> 改为 <code>mysql</code>，并填写数据库连接参数：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">storage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mysql</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  table-prefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">yuchat_</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  mysql</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">localhost</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3306</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    database</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">yuchat</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    username</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">root</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    jdbc-params</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;useSSL=false&amp;allowPublicKeyRetrieval=true&amp;autoReconnect=true&amp;useUnicode=true&amp;characterEncoding=utf8&quot;</span></span></code></pre></div><p>上线前建议：</p><ol><li>给 YuChat 单独创建数据库账号。</li><li>确认所有子服使用同一套插件版本与配置版本。</li><li>在测试服修改昵称、称呼、颜色、签名和死亡消息，确认数据会同步。</li><li>对玩家数据表、授权表和购买日志表做定期备份。</li></ol><h2 id="升级已有版本" tabindex="-1">升级已有版本 <a class="header-anchor" href="#升级已有版本" aria-label="Permalink to &quot;升级已有版本&quot;">​</a></h2><p>YuChat 会读取各配置文件的版本号，版本落后时自动合并缺失节点并保留已有值。</p><table tabindex="0"><thead><tr><th>文件</th><th>当前版本</th><th>说明</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td><code>30</code></td><td>主配置、数据库、聊天格式、显示同步、经济和声音。</td></tr><tr><td><code>messages.yml</code></td><td><code>10</code></td><td>命令、GUI、购买、输入和状态提示。</td></tr><tr><td><code>gui.yml</code></td><td><code>9</code></td><td>玩家 GUI 与管理员 GUI。</td></tr><tr><td><code>titles.yml</code></td><td><code>4</code></td><td>内置称呼。</td></tr><tr><td><code>custom_titles.yml</code></td><td><code>1</code></td><td>管理员 GUI 新建称呼。</td></tr><tr><td><code>effects.yml</code></td><td><code>3</code></td><td>颜色、渐变、彩虹和动态效果。</td></tr></tbody></table><p>升级建议：</p><ol><li>停服备份 <code>plugins/YuChat/</code>，MySQL 模式下同时备份数据库。</li><li>替换 jar。</li><li>启动一次服务端，让插件自动合并新配置。</li><li>检查控制台是否有依赖加载、数据库连接或配置格式错误。</li><li>执行 <code>/yc</code>、<code>/yc nick 测试昵称</code>、<code>/yc admin</code>、<code>/yc reload</code> 和一次聊天显示测试。</li></ol><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><ol><li>停止服务端。</li><li>删除 <code>plugins/</code> 中的 YuChat jar。</li><li>如不再需要数据，删除 <code>plugins/YuChat/</code> 目录。</li><li>MySQL 模式下按需删除 <code>yuchat_</code> 前缀相关数据表。</li></ol>`,29)])])}const u=a(s,[["render",l]]);export{k as __pageData,u as default};
